/* @lc app=leetcode id=2115 lang=kotlin */ class Solution { fun findAllRecipes(recipes: Array<String>, ingredients: List<List<String>>, supplies: Array<String>): List<String> = HashMap<String, MutableList<String>>().also { dep -> recipes.indices.forEach { i -> ingredients[i].forEach { dep.getOrPut(it) { mutableListOf() }.add(recipes[i]) } } }.let { dep -> HashMap<String, Int>().also { d -> recipes.indices.forEach { d[recipes[it]] = ingredients[it].size } }.let { d -> generateSequence(supplies.toList()) { f -> f.flatMap { dep[it].orEmpty() }.filter { d.merge(it, -1) { a, b -> a + b } == 0 }.takeIf { it.isNotEmpty() } }.drop(1).flatten().toList() } } }